        // bin_value(s) = 2*bin_value(prefix) + lastbit
        // < 2*2^(len(prefix)) + 1 = 2^(len) + 1, so in particular < 2^len
        // We do the standard tighter bound:
        // bin_value(prefix) < 2^(len-1) ==> 2*bin_value(prefix) <= 2*(2^(len-1)-1) = 2^len - 2
        // then +1 gives <= 2^len - 1 < 2^len.
